    adcs_vec3_t mapped_check_body;
    adcs_vec3_t norm_check_body;
    adcs_vec3_t norm_check_ref;
    double dot_val;
    adcs_status_t status;

    if ((body_primary == NULL) || (body_secondary == NULL) || 
        (ref_primary == NULL) || (ref_secondary == NULL) || 
        (check_body == NULL) || (check_ref == NULL) || 
        (c_bi == NULL) || (alignment == NULL)) {
        return ADCS_E_NULL;
    }

    status = adcs_triad(body_primary, body_secondary, ref_primary, ref_secondary, c_bi);
    if (status != ADCS_OK) {
        return status;
    }

    mapped_check_body = adcs_mat3_mul_vec(c_bi, check_body);

    if (adcs_vec3_normalize(&mapped_check_body, ADCS_EPS_NORM, &norm_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    if (adcs_vec3_normalize(check_ref, ADCS_EPS_NORM, &norm_check_ref) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    dot_val = adcs_vec3_dot(&norm_check_body, &norm_check_ref);
    *alignment = ADCS_CLAMP(dot_val, -1.0, 1.0);

    return ADCS_OK;
}

