    adcs_vec3_t mapped_check_body;
    adcs_vec3_t norm_mapped_check_body;
    adcs_vec3_t norm_check_body;
    double dot_product;
    adcs_status_t triad_status;

    /* Check for null pointers */
    if ((body_primary == NULL) || (body_secondary == NULL) || 
        (ref_primary == NULL) || (ref_secondary == NULL) || 
        (check_body == NULL) || (check_ref == NULL) || 
        (c_bi == NULL) || (alignment == NULL)) {
        return ADCS_E_NULL;
    }

    /* Construct C_BI using TRIAD */
    triad_status = adcs_triad(body_primary, body_secondary, ref_primary, ref_secondary, c_bi);

    /* Handle TRIAD failure: return identity, zero alignment, and status */
    if (triad_status != ADCS_OK) {
        *c_bi = adcs_mat3_identity();
        *alignment = 0.0;
        return triad_status;
    }

    /* Map check_ref from reference frame to body frame */
    mapped_check_body = adcs_mat3_mul_vec(c_bi, check_ref);

    /* Normalize mapped check vector in body frame */
    if (adcs_vec3_normalize(&mapped_check_body, ADCS_EPS_NORM, &norm_mapped_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    /* Normalize check_body vector */
    if (adcs_vec3_normalize(check_body, ADCS_EPS_NORM, &norm_check_body) != ADCS_OK) {
        return ADCS_E_DEGENERATE;
    }

    /* Calculate dot alignment between normalized vectors */
    dot_product = adcs_vec3_dot(&norm_mapped_check_body, &norm_check_body);

    /* Clamp alignment to [-1, 1] */
    if (dot_product < -1.0) {
        dot_product = -1.0;
    } else if (dot_product > 1.0) {
        dot_product = 1.0;
    }

    /* Assign final alignment value */
    *alignment = dot_product;

    return ADCS_OK;
}

